import numpy as np

def count_crossings(mask):
    m = np.asarray(mask, dtype=bool)
    rows = np.sum(m[:, 0]) + np.sum(m[:, 1:] & ~m[:, :-1])
    cols = np.sum(m[0, :]) + np.sum(m[1:, :] & ~m[:-1, :])
    return int(rows + cols)

def mean_intercept(mask, pixel_size):
    m = np.asarray(mask, dtype=bool)
    n_rows, n_cols = m.shape
    return 2 * n_rows * n_cols * pixel_size / count_crossings(m)
